function project(lon, lat) {
  var clamped = Math.max(LAT_BOTTOM, Math.min(LAT_TOP, lat))
  return [(lon + 180) / 360 * WIDTH, (LAT_TOP - clamped) / (LAT_TOP - LAT_BOTTOM) * HEIGHT]
}

